#!/usr/bin/env node
'use strict'

// Copies the Vale style and the page templates from a checkout of
// redpanda-data/docs-team-standards into vendor/dts/, and checks that copy.
//
// docs-team-standards (DTS) is the source of both, but it is a private Claude
// Code plugin that content repos never install. Shipping a copy in this
// package lets the docs language server offer the templates as snippets and
// run the Vale rules with no checkout path to configure and no network.
//
// The copy is byte-identical to the source, so a snippet renders exactly the
// template's text and .vale.ini still finds its styles at the relative
// StylesPath. Provenance lives beside it instead of inside it: manifest.json
// records the DTS commit and a sha256 for every file, and README.adoc carries
// the generated-content marker.
//
// Modes:
//   --source <dts>            write vendor/dts/ from the checkout (the sync)
//   --source <dts> --check    report what a sync would change, write nothing
//   --verify                  check vendor/dts/ against its own manifest
//
// Exit: 0 in sync or verified, 1 drift or a failed verify, 2 could not run.

const crypto = require('crypto')
const fs = require('fs')
const path = require('path')
const { execFileSync } = require('child_process')

const SOURCE_REPO = 'redpanda-data/docs-team-standards'
const DEFAULT_DEST = path.join(__dirname, '..', '..', 'vendor', 'dts')
const MANIFEST = 'manifest.json'
const README = 'README.adoc'

// What is copied. Everything else in DTS (skills, prompts, fixtures, scripts)
// stays private. A file reaches the public npm package only by matching one of
// these, so widening a pattern is a publishing decision.
//
// `required: false` means the source directory may be absent, in which case
// the copy has none of that group. A directory that exists must still contain
// the group's required files, so a half-moved style fails instead of shipping.
const GROUPS = [
  {
    from: 'resources/templates',
    to: 'templates',
    required: true,
    include: (rel) => /^[^/]+-template\.adoc$/.test(rel),
    mustHave: [],
  },
  {
    from: 'vale',
    to: 'vale',
    required: false,
    include: (rel) => rel === '.vale.ini' || rel.startsWith('styles/'),
    mustHave: ['.vale.ini'],
  },
]

const GENERATED_LINE = '// This content is autogenerated. Do not edit manually. ' +
  `Generated by .github/scripts/sync-dts-vendor.js from ${SOURCE_REPO}. ` +
  'Change the files in that repository; the daily sync opens a pull request here.'

const README_TEXT = `${GENERATED_LINE}
= Vendored docs-team-standards files

Copies of the Vale style and the page templates from ${SOURCE_REPO}, which is the source of both.
They ship in this package so the docs language server can use them offline.

* \`templates/\`: \`resources/templates/*-template.adoc\`, one per topic type.
* \`vale/\`: \`vale/.vale.ini\` and \`vale/styles/\`. Run \`vale --config vendor/dts/vale/.vale.ini <file>\`.
* \`${MANIFEST}\`: the source commit and a sha256 for every file.

Every file is byte-identical to its source.
The \`sync-dts-vendor\` workflow refreshes the copy every day and opens a pull request when it changes.
The tests fail if a file here no longer matches the manifest.

This package is public on npm, so anything added to these source paths in ${SOURCE_REPO} becomes public when the sync pull request merges.
`

class SyncError extends Error {}

const sha256 = (buf) => crypto.createHash('sha256').update(buf).digest('hex')

// Recursive listing of regular files under dir, as POSIX relative paths.
// Anything else (symlink, socket, device) is an error: lstat, never stat, so a
// link cannot pull a file from outside the checkout into a public package.
function walk (dir, base = dir, out = []) {
  for (const name of fs.readdirSync(dir).sort()) {
    const abs = path.join(dir, name)
    const st = fs.lstatSync(abs)
    const rel = path.relative(base, abs).split(path.sep).join('/')
    if (st.isDirectory()) walk(abs, base, out)
    else if (st.isFile()) out.push(rel)
    else out.push({ irregular: rel })
  }
  return out
}

function collect (sourceRoot) {
  const entries = []
  for (const g of GROUPS) {
    const dir = path.join(sourceRoot, g.from)
    if (!fs.existsSync(dir)) {
      if (g.required) throw new SyncError(`${g.from}/ is missing from the ${SOURCE_REPO} checkout at ${sourceRoot}.`)
      continue
    }
    const picked = []
    for (const rel of walk(dir)) {
      if (typeof rel !== 'string') {
        if (g.include(rel.irregular)) throw new SyncError(`${g.from}/${rel.irregular} is not a regular file; refusing to copy it.`)
        continue
      }
      if (g.include(rel)) picked.push(rel)
    }
    if (picked.length === 0) throw new SyncError(`${g.from}/ has no files to copy.`)
    for (const need of g.mustHave) {
      if (!picked.includes(need)) throw new SyncError(`${g.from}/${need} is missing.`)
    }
    if (g.from === 'vale' && !picked.some((r) => r.startsWith('styles/'))) {
      throw new SyncError('vale/styles/ has no rule files.')
    }
    for (const rel of picked) {
      entries.push({ dest: `${g.to}/${rel}`, source: `${g.from}/${rel}`, abs: path.join(dir, rel) })
    }
  }
  return entries.sort((a, b) => (a.dest < b.dest ? -1 : 1))
}

// The last commit that touched the copied paths, not the checkout's HEAD, so
// an unrelated DTS commit leaves the manifest unchanged and opens no PR.
function sourceCommit (sourceRoot) {
  const paths = GROUPS.map((g) => g.from).filter((p) => fs.existsSync(path.join(sourceRoot, p)))
  let out
  try {
    out = execFileSync('git', ['-C', sourceRoot, 'log', '-1', '--format=%H', '--', ...paths], {
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'pipe'],
    }).trim()
  } catch (err) {
    throw new SyncError(`could not read the commit history of ${sourceRoot}: ${err.message.split('\n')[0]}`)
  }
  if (!/^[0-9a-f]{40}$/.test(out)) {
    throw new SyncError(`no commit touches ${paths.join(', ')} in ${sourceRoot} (a shallow clone has no history; clone with --filter=blob:none instead).`)
  }
  return out
}

// The full expected content of vendor/dts/, as { relPath: Buffer }.
function render (sourceRoot) {
  const entries = collect(sourceRoot)
  const files = {}
  const out = {}
  for (const e of entries) {
    const buf = fs.readFileSync(e.abs)
    out[e.dest] = buf
    files[e.dest] = { source: e.source, sha256: sha256(buf) }
  }
  const manifest = {
    generated: GENERATED_LINE.replace(/^\/\/ /, ''),
    source: { repository: SOURCE_REPO, commit: sourceCommit(sourceRoot) },
    files,
  }
  out[MANIFEST] = Buffer.from(JSON.stringify(manifest, null, 2) + '\n')
  out[README] = Buffer.from(README_TEXT)
  return out
}

function readTree (dest) {
  const tree = {}
  if (!fs.existsSync(dest)) return tree
  for (const rel of walk(dest)) {
    if (typeof rel !== 'string') tree[rel.irregular] = null
    else tree[rel] = fs.readFileSync(path.join(dest, rel))
  }
  return tree
}

// Differences between the expected tree and what is on disk.
function diff (expected, actual) {
  const changes = []
  for (const rel of Object.keys(expected).sort()) {
    if (!(rel in actual)) changes.push(`added: ${rel}`)
    else if (actual[rel] === null || !actual[rel].equals(expected[rel])) changes.push(`changed: ${rel}`)
  }
  for (const rel of Object.keys(actual).sort()) {
    if (!(rel in expected)) changes.push(`removed: ${rel}`)
  }
  return changes
}

function sync (sourceRoot, dest) {
  const expected = render(sourceRoot)
  const changes = diff(expected, readTree(dest))
  if (changes.length === 0) return changes
  fs.rmSync(dest, { recursive: true, force: true })
  for (const [rel, buf] of Object.entries(expected)) {
    const abs = path.join(dest, rel)
    fs.mkdirSync(path.dirname(abs), { recursive: true })
    fs.writeFileSync(abs, buf)
  }
  return changes
}

function check (sourceRoot, dest) {
  return diff(render(sourceRoot), readTree(dest))
}

// vendor/dts/ against its own manifest: every listed file present with its
// hash, nothing unlisted, README unchanged. Catches a hand edit or a partial
// copy without needing the private source.
function verify (dest) {
  const problems = []
  const mpath = path.join(dest, MANIFEST)
  let manifest
  try {
    manifest = JSON.parse(fs.readFileSync(mpath, 'utf8'))
  } catch (err) {
    return [`${MANIFEST} is missing or not valid JSON: ${err.message.split('\n')[0]}`]
  }
  if (!manifest || typeof manifest.files !== 'object' || manifest.files === null) {
    return [`${MANIFEST} has no "files" object.`]
  }
  if (!manifest.source || !/^[0-9a-f]{40}$/.test(String(manifest.source.commit))) {
    problems.push(`${MANIFEST} has no 40-character source.commit.`)
  }
  const tree = readTree(dest)
  for (const [rel, meta] of Object.entries(manifest.files)) {
    if (!(rel in tree)) problems.push(`missing: ${rel}`)
    else if (tree[rel] === null) problems.push(`not a regular file: ${rel}`)
    else if (sha256(tree[rel]) !== meta.sha256) problems.push(`edited: ${rel} no longer matches its sha256 in ${MANIFEST}`)
  }
  for (const rel of Object.keys(tree)) {
    if (rel === MANIFEST || rel === README) continue
    if (!(rel in manifest.files)) problems.push(`unlisted: ${rel} is not in ${MANIFEST}`)
  }
  if (!tree[README] || !tree[README].equals(Buffer.from(README_TEXT))) problems.push(`edited: ${README} differs from the text the sync writes`)
  return problems
}

function main (argv) {
  const args = { check: false, verify: false, source: null, dest: DEFAULT_DEST }
  for (let i = 0; i < argv.length; i++) {
    const a = argv[i]
    if (a === '--check') args.check = true
    else if (a === '--verify') args.verify = true
    else if (a === '--source') args.source = argv[++i]
    else if (a === '--dest') args.dest = argv[++i]
    else {
      console.error(`unknown argument: ${a}`)
      return 2
    }
  }
  try {
    if (args.verify) {
      const problems = verify(args.dest)
      for (const p of problems) console.error(p)
      if (problems.length) {
        console.error(`vendor/dts/ does not match its manifest. Run the sync-dts-vendor workflow, or change the files in ${SOURCE_REPO}.`)
        return 1
      }
      console.log('vendor/dts/ matches its manifest.')
      return 0
    }
    if (!args.source) {
      console.error('--source <docs-team-standards checkout> is required unless --verify is given.')
      return 2
    }
    const changes = args.check ? check(args.source, args.dest) : sync(args.source, args.dest)
    for (const c of changes) console.log(c)
    if (args.check && changes.length) {
      console.error(`vendor/dts/ is behind ${SOURCE_REPO}: ${changes.length} file(s) differ.`)
      return 1
    }
    if (!changes.length) console.log(`vendor/dts/ is in sync with ${SOURCE_REPO}.`)
    return 0
  } catch (err) {
    if (err instanceof SyncError) {
      console.error(`::error::${err.message}`)
      return 2
    }
    throw err
  }
}

module.exports = { GROUPS, README_TEXT, GENERATED_LINE, collect, render, sync, check, verify, main }

if (require.main === module) process.exitCode = main(process.argv.slice(2))
